toolArgs.file_text:
.message-item {
    padding: 0.5rem 0.75rem;
    border-radius: 6px;
    position: relative;
    transition: background 0.1s;
}

.message-item:hover {
    background: #2c2f33;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
    margin-bottom: 0.15rem;
}

.message-author {
    font-weight: 700;
    font-size: 0.9rem;
    color: #fff;
}

.message-time {
    font-size: 0.72rem;
    color: #777;
}

.message-content {
    font-size: 0.9rem;
    line-height: 1.4;
    color: #ddd;
}

.message-reactions {
    display: flex;
    gap: 0.35rem;
    margin-top: 0.35rem;
    flex-wrap: wrap;
}

.reaction-badge {
    background: #2c2f33;
    border: 1px solid #444;
    border-radius: 12px;
    padding: 0.15rem 0.5rem;
    font-size: 0.8rem;
    cursor: pointer;
    color: #ddd;
    transition: background 0.1s;
}

.reaction-badge:hover {
    background: #3a3d42;
    border-color: #5865f2;
}

.thread-link {
    background: none;
    border: none;
    color: #5865f2;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 0.2rem 0;
    margin-top: 0.25rem;
    font-weight: 600;
}

.thread-link:hover {
    text-decoration: underline;
}

.message-actions {
    position: absolute;
    top: -0.5rem;
    right: 0.5rem;
    display: flex;
    gap: 0.25rem;
    background: #1a1d21;
    border: 1px solid #444;
    border-radius: 6px;
    padding: 0.2rem 0.3rem;
    box-shadow: 0 2px 8px rgba(0,0,0,0.3);
}

.action-btn {
    background: none;
    border: none;
    color: #ccc;
    font-size: 0.75rem;
    cursor: pointer;
    padding: 0.2rem 0.5rem;
    border-radius: 4px;
}

.action-btn:hover {
    background: #2c2f33;
    color: #fff;
}

.emoji-picker-container {
    position: relative;
}

.emoji-picker {
    position: absolute;
    top: 100%;
    right: 0;
    background: #1a1d21;
    border: 1px solid #444;
    border-radius: 6px;
    padding: 0.3rem;
    display: flex;
    gap: 0.2rem;
    box-shadow: 0 2px 8px rgba(0,0,0,0.3);
    z-index: 10;
}

.emoji-option {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 0.2rem;
    border-radius: 4px;
}

.emoji-option:hover {
    background: #2c2f33;
}

